public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    Set<V> vertices1 = new HashSet<>();
    Set<V> vertices2 = new HashSet<>();

    int vertexCount = target.getNumVertices() / 2;
    for (int i = 0; i < vertexCount; i++) {
        vertices1.add(target.getVertex(i));
    }
    for (int i = vertexCount; i < 2 * vertexCount; i++) {
        vertices2.add(target.getVertex(i));
    }

    for (V v1 : vertices1) {
        for (V v2 : vertices2) {
            target.addEdge(v1, v2, null);
        }
    }

    resultMap.put("vertices1", (V) vertices1);
    resultMap.put("vertices2", (V) vertices2);
}

