public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.encode(message, buffer);
    int size = data.length;
    out.write(size >>> 24);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    out.write(data);
    return size + 4;
}

try (BufferedOutputStream bufferedOut = new BufferedOutputStream(out)) {
    // Calculate the length of the message and write it as a byte
    byte[] messageBytes = schema.toBytes(message);
    byte[] lengthBytes = ByteBuffer.allocate(4).putInt(messageBytes.length).array();
    bufferedOut.write(lengthBytes);
    // Write the message bytes to the output stream
    bufferedOut.write(messageBytes);
    // Flush the output stream to ensure all data is written
    bufferedOut.flush();
    // Return the length of the message
    return messageBytes.length;
} catch (IOException e) {
    throw new IOException("Error writing delimited message", e);
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] bytes = schema.toBytes(message);
    int len = bytes.length;
    out.write(len >>> 24);
    out.write(len >>> 16);
    out.write(len >>> 8);
    out.write(len);
    out.write(bytes, 0, bytes.length);
    return len + 5;
}

