public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        TypeVariable<?>[] typeParameters = targetType.getTypeParameters();

        Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
        for (int i = 0; i < typeParameters.length; i++) {
            typeVariableMap.put(typeParameters[i], typeArguments[i]);
        }

        Class<?>[] resolvedTypes = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            if (typeArgument instanceof Class<?>) {
                resolvedTypes[i] = (Class<?>) typeArgument;
            } else if (typeArgument instanceof ParameterizedType) {
                resolvedTypes[i] = resolveRawClass((ParameterizedType) typeArgument, typeVariableMap);
            } else if (typeArgument instanceof WildcardType) {
                WildcardType wildcardType = (WildcardType) typeArgument;
                List<Type> upperBounds = new ArrayList<>(Arrays.asList(wildcardType.getUpperBounds()));
                List<Type> lowerBounds = Arrays.asList(wildcardType.getLowerBounds());
                // Handle upper and lower bounds as needed
                resolvedTypes[i] = upperBounds.isEmpty() ? Object.class : resolveRawClass((ParameterizedType) upperBounds.get(0), typeVariableMap);
            }
        }
        return resolvedTypes;
    } else {
        return null;
    }
}

