    Set<String> existingFields = mappings.getFields();

    // Get all fields from the index
    Index index = getIndexForTable(tableName);
    if (index != null) {
        Set<String> indexFields = index.getFields();

        // Find fields that exist in the index but not in the input mappings
        for (String field : indexFields) {
            if (!existingFields.contains(field) && !field.equals("_source")) {
                diffMappings.add(field);
            }
        }
    }

    return diffMappings;
}

