static long compressTimeBucket(long timeBucket, int dayStep) {
    long dayStart = timeBucket - (timeBucket % dayStep);
    long dayEnd = dayStart + dayStep - 1;
    return dayStart + (timeBucket - dayStart) / dayStep * dayStep;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket % dayStep);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long day = timeBucket % 100;
    long month = (timeBucket / 100) % 100;
    long year = timeBucket / 10000;

    if (dayStep == 1) {
        return timeBucket;
    } else {
        day = (day / dayStep) * dayStep;
        if (day == 0) {
            month--;
            day = dayStep;
        }
        if (month == 0) {
            year--;
            month = 12;
        }
        return year * 10000 + month * 100 + day;
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long day = timeBucket % 100;
    long yearMonth = timeBucket / 100;
    if (dayStep == 0) {
        return yearMonth * 100 + day;
    } else if (dayStep == 1) {
        long nextDay = (day + 1) % 28;
        return yearMonth * 100 + nextDay;
    } else if (dayStep == 2) {
        long nextDay = (day + 2) % 28;
        return yearMonth * 100 + nextDay;
    } else if (dayStep == 3) {
        long nextDay = (day + 3) % 28;
        return yearMonth * 100 + nextDay;
    } else if (dayStep == 4) {
        long nextDay = (day + 4) % 28;
        return yearMonth * 100 + nextDay;
    } else if (dayStep == 5) {
        long nextDay = (day + 5) % 28;
        return yearMonth * 100 + nextDay;
    } else if (dayStep == 6) {
        long nextDay = (day + 6) % 28;
        return yearMonth * 100 + nextDay;
    } else if (dayStep == 7) {
        long nextDay = (day + 7) % 28;
        return yearMonth * 100 + nextDay;
    } else if (dayStep == 8) {
        long nextDay = (day + 8) % 28;
