public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index, end = index + len; i < end; i++) {
        final char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int result = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if ((c & 0x80) == 0) {
            result += 1;
        } else if ((c & 0xE0) == 0xC0) {
            result += 2;
        } else if ((c & 0xF0) == 0xE0) {
            result += 3;
        } else if ((c & 0xF8) == 0xF0) {
            result += 4;
        } else {
            result += 1; // Unpaired surrogate
        }
    }
    return result;
}

