int nextPrime(int desiredCapacity) {
    int capacity = desiredCapacity;
    while (!isPrime(capacity)) {
        capacity++;
        if (desiredCapacity >= 1000) {
            if (capacity - desiredCapacity > desiredCapacity * 0.11) {
                capacity = (int) (desiredCapacity * 1.11);
                while (!isPrime(capacity)) {
                    capacity++;
                }
                break;
            }
        }
    }
    return capacity;
}

int function(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    boolean found = false;
    while (!found) {
        if (isPrime(candidate)) {
            found = true;
        } else {
            candidate++;
            if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
                throw new IllegalArgumentException("No prime number within 11% of desired capacity found.");
            }
        }
    }
    return candidate;
}

private boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

